"""Run the canonical jianying-direct-call skill without duplicating its code."""
import hashlib
import json
import os
from pathlib import Path
import runpy
import sys


def _helper():
    explicit = os.environ.get('JY_DIRECT_SKILL_ROOT')
    roots = [Path(explicit)] if explicit else []
    config = Path.home() / '.config/codex-skills/sync.json'
    if not explicit and config.is_file():
        try:
            repo = json.loads(config.read_text()).get('repo')
            if repo:
                roots.append(Path(repo) / 'skills/jianying-direct-call')
        except (OSError, ValueError):
            pass
    if not explicit:
        roots.extend(Path.home() / folder / 'jianying-direct-call'
                     for folder in ('.agents/skills', '.codex/skills'))
    for root in roots:
        candidate = root / 'scripts/jianying.py'
        if candidate.is_file() and candidate.resolve() != Path(__file__).resolve():
            return candidate
    raise ImportError('Install jianying-direct-call or set JY_DIRECT_SKILL_ROOT to its folder')


def source_identity():
    """Describe the selected local Python implementation, without loading it."""
    source = _helper().resolve()
    scripts = source.parent
    files = {}
    for path in sorted(scripts.rglob('*.py')):
        if '__pycache__' not in path.parts:
            files[path.relative_to(scripts).as_posix()] = hashlib.sha256(path.read_bytes()).hexdigest()
    return {
        'skill_root': str(scripts.parent),
        'entrypoint': str(source),
        'python_sources_sha256': hashlib.sha256(
            json.dumps(files, sort_keys=True).encode()).hexdigest(),
    }


